#include <stdio.h>
int main(void) {
    int x = 5;
    int y = x++;
    printf("%d %d\n", x, y);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 5;
    double b = 2.0;
    printf("%.2f\n", a / b + 1);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 0, b = 5;
    if (a != 0 && b / a > 1) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int i = 5;
    int a = i++;
    int b = ++i;
    printf("%d %d %d\n", a, b, i);
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = 12;
    int y = 10;
    printf("%d\n", x ^ y);
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = 10;
    x += 5;
    x *= 2;
    x -= 3;
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 5, b = 10, c = 15;
    int max = (a > b) ? (a > c ? a : c) : (b > c ? b : c);
    printf("%d\n", max);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 5, b = 2, c = 3;
    int r = a + b * c - a / b;
    printf("%d\n", r);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = (1, 2, 3);
    printf("%d\n", a);
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = -1;
    printf("%d\n", x >> 1);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 5;
    double b = 2.0;
    printf("%zu\n", sizeof(a + b));
    return 0;
}
